def list_to_float(lst):
    result = []
    for tup in lst:
        new_tup = []
        for item in tup:
            try:
                new_tup.append(float(item))
            except (ValueError, TypeError):
                new_tup.append(item)
        result.append(tuple(new_tup))
    return result
